import numpy as np
import xarray as xr
import pytest

def test_dataset_interp_datetime():
    ds = xr.Dataset(
        data_vars={
            "time": (("x",), np.array([1, 2]).astype("datetime64[ns]")),
            "val": (("x",), np.array([1.0, 2.0])),
        },
        coords={"x": [0, 1]},
    )

    # This should raise TypeError to be consistent with DataArray.interp
    try:
        ds.interp(x=[0, 0.5, 1])
    except TypeError:
        print("Caught expected TypeError")
        return
    except Exception as e:
        print(f"Caught unexpected exception: {type(e).__name__}: {e}")
        exit(1)
    else:
        print("Dataset.interp() silently dropped the datetime array!")
        exit(1)

def test_dataarray_interp_datetime():
    da = xr.DataArray(
        np.array([1, 2]).astype("datetime64[ns]"),
        dims="x",
        coords={"x": [0, 1]},
    )
    try:
        da.interp(x=[0, 0.5, 1])
    except TypeError:
        print("DataArray.interp() raised expected TypeError")
    else:
        print("DataArray.interp() did NOT raise TypeError!")
        exit(1)

if __name__ == "__main__":
    test_dataarray_interp_datetime()
    test_dataset_interp_datetime()
